    out.nonGating = c0.state;
    out.houndAlive = HO.hostiles.some((e) => e.kind === 'hound');
    // control: the same body without the opt-out holds the gate
    c0.state = 'done';
    while (HO.hostiles.length) HO.removeHostile(0, false);
